ription\":\"Power measurement transducer's time constant, in s. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"e_lim\":{\"description\":\"Error limit in PI controller for q control (e_min, e_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"Kpq\":{\"description\":\"PI controller proportional gain for q control\",\"type\":\"number\"},\"Kiq\":{\"description\":\"PI controller integral gain for q control\",\"type\":\"number\"},\"Iqr_lim\":{\"description\":\"Limit on rate of change for reactive current (pu/s) (Iqr_min, Iqr_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"I_max\":{\"description\":\"Max. inverter's current\",\"type\":\"number\"},\"Tg\":{\"description\":\"Current control's time constant, in s. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"kWh_Cap\":{\"description\":\"BESS capacity in kWh\",\"type\":\"number\"},\"SOC_ini\":{\"description\":\"Initial state of charge (SOC) in pu\",\"type\":\"number\"},\"SOC_lim\":{\"description\":\"Battery's SOC limits (SOC_min, SOC_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"Trf\":{\"description\":\"Time constant to estimate system frequency, in s. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"fdbd_pnts\":{\"description\":\"Frequency error dead band thresholds `(fdbd1, fdbd2)`\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/FdbdPnts\"},\"D_dn\":{\"description\":\"reciprocal of droop for over-frequency conditions, in pu\",\"type\":\"number\"},\"D_up\":{\"description\":\"reciprocal of droop for under-frequency conditions, in pu\",\"type\":\"number\"},\"fe_lim\":{\"description\":\"Frequency error limits in pu (fe_min, fe_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"Kpp\":{\"description\":\"PI controller proportional gain for p control\",\"type\":\"number\"},\"Kip\":{\"description\":\"PI controller integral gain for p control\",\"type\":\"number\"},\"P_lim\":{\"description\":\"Active power limits in pu (P_min, P_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"dP_lim\":{\"description\":\"Ramp rate limits for active power in pu/s (dP_min, dP_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"T_pord\":{\"description\":\"Power filter time constant in s. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"rrpwr\":{\"description\":\"Ramp rate for real power increase following a fault, in pu/s\",\"type\":\"number\"},\"VRT_pnts\":{\"description\":\"Voltage ride through v points (vrt1,vrt2,vrt3,vrt4,vrt5)\",\"\$ref\":\"https://openapi.invalid/schema/external-1c4b7abd3c66ae6d8393.json#/\$defs/VoltageRideThroughPnts\"},\"TVRT_pnts\":{\"description\":\"Voltage ride through time points (tvrt1,tvrt2,tvrt3)\",\"\$ref\":\"https://openapi.invalid/schema/external-1c4b7abd3c66ae6d8393.json#/\$defs/VoltageRideThroughTimePnts\"},\"tV_delay\":{\"description\":\"Time delay for reconnection after voltage ride-through disconnection. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"VES_lim\":{\"description\":\"Min and max voltage for entering service (VES_min,VES_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"FRT_pnts\":{\"description\":\"Frequency ride through v points (frt1,frt2,frt3,frt4)\",\"\$ref\":\"https://openapi.invalid/schema/external-1c4b7abd3c66ae6d8393.json#/\$defs/FrequencyRideThroughPnts\"},\"TFRT_pnts\":{\"description\":\"Frequency ride through time points (tfrt1,tfrt2)\",\"\$ref\":\"https://openapi.invalid/schema/external-1c4b7abd3c66ae6d8393.json#/\$defs/FrequencyRideThroughTimePnts\"},\"tF_delay\":{\"description\":\"Time delay for reconnection after frequency ride-through disconnection. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"FES_lim\":{\"description\":\"Min and max frequency for entering service (FES_min,FES_max)\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"Pfa_ref\":{\"description\":\"Reference power factor\",\"type\":\"number\",\"default\":0.0},\"Q_ref\":{\"description\":\"Reference reactive power, in pu. Units: pu.\",\"type\":\"number\",\"default\":0.0,\"x-unit\":\"pu\",\"x-quantity\":\"ReactivePower\"},\"P_ref\":{\"description\":\"Reference active power, in pu. Units: pu.\",\"type\":\"number\",\"default\":1.0,\"x-unit\":\"pu\",\"x-quantity\":\"ActivePower\"},\"base_power\":{\"description\":\"Base power for the per-unit parameters of this model. Usually equal to the `base_power` of the static injection device that names this model. Units: MVA.\",\"type\":\"number\",\"exclusiveMinimum\":0,\"x-unit\":\"MVA\"}},\"required\":[\"id\",\"name\",\"Qref_Flag\",\"PQ_Flag\",\"Gen_Flag\",\"PerOp_Flag\",\"Recon_Flag\",\"Trv\",\"VV_pnts\",\"Q_lim\",\"Tp\",\"e_lim\",\"Kpq\",\"Kiq\",\"Iqr_lim\",\"I_max\",\"Tg\",\"kWh_Cap\",\"SOC_ini\",\"SOC_lim\",\"Trf\",\"fdbd_pnts\",\"D_dn\",\"D_up\",\"fe_lim\",\"Kpp\",\"Kip\",\"P_lim\",\"dP_lim\",\"T_pord\",\"rrpwr\",\"VRT_pnts\",\"TVRT_pnts\",\"tV_delay\",\"VES_lim\",\"FRT_pnts\",\"TFRT_pnts\",\"tF_delay\",\"FES_lim\",\"base_power\"],\"\$defs\":{\"FrequencyRideThroughPnts\":{\"description\":\"The four frequency points `(frt1, ..., frt4)` of a frequency ride-through characteristic.\",\"properties\":{\"frt1\":{\"type\":\"number\"},\"frt2\":{\"type\":\"number\"},\"frt3\":{\"type\":\"number\"},\"frt4\":{\"type\":\"number\"}},\"required\":[\"frt1\",\"frt2\",\"frt3\",\"frt4\"],\"title\":\"FrequencyRideThroughPnts\",\"type\":\"object\"},\"FrequencyRideThroughTimePnts\":{\"description\":\"The two time points `(tfrt1, tfrt2)` of a frequency ride-through characteristic.\",\"properties\":{\"tfrt1\":{\"type\":\"number\"},\"tfrt2\":{\"type\":\"number\"}},\"required\":[\"tfrt1\",\"tfrt2\"],\"title\":\"FrequencyRideThroughTimePnt