        media_type="application/schema+json",
        json="{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Modified ESAC1A. This excitation systems consists of an alternator main exciter feeding its output via non-controlled rectifiers. The exciter does not employ self-excitation, and the voltage regulator power is taken from a source that is not affected by external transients. Parameters of IEEE Std 421.5 Type AC1A. EXAC1 in PSSE and PSLF\",\"properties\":{\"id\":{\"description\":\"Unique integer identifier for this component\",\"type\":\"integer\"},\"Tr\":{\"description\":\"Regulator input filter time constant. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"Tb\":{\"description\":\"Regulator denominator (lag) time constant. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"Tc\":{\"description\":\"Regulator numerator (lead) time constant. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"Ka\":{\"description\":\"Regulator output gain\",\"type\":\"number\"},\"Ta\":{\"description\":\"Regulator output time constant. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"Vr_lim\":{\"description\":\"Limits for regulator output\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"Te\":{\"description\":\"Exciter field time constant. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"Kf\":{\"description\":\"Rate feedback excitation system stabilizer gain\",\"type\":\"number\"},\"Tf\":{\"description\":\"Rate feedback time constant. Units: s.\",\"type\":\"number\",\"x-unit\":\"s\"},\"Kc\":{\"description\":\"Rectifier loading factor proportional to commutating reactance\",\"type\":\"number\"},\"Kd\":{\"description\":\"Demagnetizing factor, function of exciter alternator reactances\",\"type\":\"number\"},\"Ke\":{\"description\":\"Exciter field proportional constant\",\"type\":\"number\"},\"E_sat\":{\"type\":\"array\",\"description\":\"Exciter output voltage for saturation factor\",\"items\":{\"type\":\"number\"},\"minItems\":2,\"maxItems\":2},\"Se\":{\"type\":\"array\",\"description\":\"Exciter saturation factor at exciter output voltage\",\"items\":{\"type\":\"number\"},\"minItems\":2,\"maxItems\":2},\"V_ref\":{\"description\":\"Reference voltage set-point\",\"default\":1.0,\"type\":\"number\"}},\"required\":[\"id\",\"Tr\",\"Tb\",\"Tc\",\"Ka\",\"Ta\",\"Vr_lim\",\"Te\",\"Kf\",\"Tf\",\"Kc\",\"Kd\",\"Ke\",\"E_sat\",\"Se\"],\"title\":\"EXAC1\",\"type\":\"object\"}",
