    (
        id="https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json",
        retrieval="https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json",
        media_type="application/schema+json",
        json="{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"\$defs\":{\"ACBusType\":{\"description\":\"Classification of an AC bus for power flow, following the MATPOWER bus-type convention. `PQ` marks a bus with no in-service generation that regulates voltage; it can still have a `voltage_setpoint` that remote devices hold, or that a droop or a reactive power limit stops them from reaching. `PV` marks a bus with in-service generation that regulates voltage: generators, storage, synchronous condensers or sources. Those devices hold the `voltage_setpoint` of the bus they regulate, this bus or their `remote_regulated_bus`; `REF` names the reference for the system voltage angle; `SLACK` balances the system active and reactive mismatch and sets the reference angle; `ISOLATED` marks a bus not connected to the network.\",\"enum\":[\"PQ\",\"PV\",\"REF\",\"ISOLATED\",\"SLACK\"],\"title\":\"ACBusType\",\"type\":\"string\"},\"AverageRateCurve\":{\"description\":\"A curve whose y values are the average rate `f(x)/x` at production level `x` — total cost or fuel divided by output, the form heat rate tables use when they report MMBtu/MWh against MW. `initial_input` records the total input at the minimum production point and is what makes conversion to an `InputOutputCurve` possible. Use `IncrementalCurve` when the data gives marginal rather than average rates.\",\"properties\":{\"curve_type\":{\"const\":\"AVERAGE_RATE\",\"type\":\"string\",\"default\":\"AVERAGE_RATE\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\",\"PIECEWISE_STEP\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseStepData\"}]},\"initial_input\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the curve's y-axis unit.\"},\"input_at_zero\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the curve's y-axis unit.\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"AverageRateCurve\",\"type\":\"object\",\"x-curve-output\":-1},\"ComplexNumber\":{\"description\":\"A complex number, given as its `real` and `imag` parts.\",\"properties\":{\"real\":{\"type\":\"number\"},\"imag\":{\"type\":\"number\"}},\"title\":\"ComplexNumber\",\"type\":\"object\"},\"CostCurve\":{\"description\":\"Variable operation cost of a device expressed directly in currency. Wraps a `ValueCurve` that may be in input-output, incremental, or average-rate form, with `power_units` declaring the basis of the x axis and `vom_cost` adding a proportional variable operation and maintenance term. Units: x-axis per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu ; y-axis USD/h .\",\"properties\":{\"power_units\":{\"default\":\"NATURAL_UNITS\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/UnitSystem\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ValueCurve\"},\"variable_cost_type\":{\"const\":\"COST\",\"type\":\"string\",\"default\":\"COST\"},\"vom_cost\":{\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"}},\"required\":[\"value_curve\",\"power_units\",\"vom_cost\",\"variable_cost_type\"],\"title\":\"CostCurve\",\"type\":\"object\",\"x-curve-axes\":{\"x\":\"ActivePower\",\"y\":\"CostPerTime\"}},\"DbdPnts\":{\"description\":\"A pair of deadband thresholds `(dbd1, dbd2)` on a voltage or reactive-power error signal, inside which the controller does not act.\",\"properties\":{\"dbd1\":{\"type\":\"number\"},\"dbd2\":{\"type\":\"number\"}},\"title\":\"DbdPnts\",\"type\":\"object\"},\"EmissionBasis\":{\"description\":\"What an emission rate is measured against: `FUEL_INPUT` for mass per unit of heat input, `POWER_OUTPUT` for mass per unit of electrical output. The choice constrains the accompanying energy unit — a heat unit for `FUEL_INPUT`, `MWH` for `POWER_OUTPUT`.\",\"enum\":[\"FUEL_INPUT\",\"POWER_OUTPUT\"],\"title\":\"EmissionBasis\",\"type\":\"string\"},\"EnergyUnit\":{\"description\":\"Energy unit forming the denominator of an emission rate: `MMBTU` or `GJ` for a fuel-input basis, `MWH` for a power-output basis.\",\"enum\":[\"MMBTU\",\"GJ\",\"MWH\"],\"title\":\"EnergyUnit\",\"type\":\"string\"},\"EnergyUnitBasis\":{\"description\":\"Unit basis a stored-energy quantity is recorded in (distinct from EnergyUnit, which names fuel energy content). MWH: megawatt-hours, the conventional interchange form. MWMIN: megawatt-minutes, consistent with the minutes basis used for operational durations, so a duration computed as energy over power comes out in minutes with no hidden factor of 60. Defaults to MWH: MWMIN is supported, not preferred.\",\"enum\":[\"MWH\",\"MWMIN\"],\"title\":\"EnergyUnitBasis\",\"type\":\"string\"},\"FdbdPnts\":{\"description\":\"A pair of deadband thresholds `(fdbd1, fdbd2)` on a frequency error signal, inside which the controller does not act.\",\"properties\":{\"fdbd1\":{\"type\":\"number\"},\"fdbd2\":{\"type\":\"number\"}},\"title\":\"FdbdPnts\",\"type\":\"object\"},\"FromTo\":{\"description\":\"A pair of values, one at the `from` end and one at the `to` end of a directed edge.\",\"properties\":{\"from\":{\"title\":\"From\",\"type\":\"number\"},\"to\":{\"title\":\"To\",\"type\":\"number\"}},\"title\":\"FromTo\",\"type\":\"object\"},\"FromTo_ToFrom\":{\"description\":\"A pair of values for a directed edge, one for each orientation: `from_to` and `to_from`. The two are carried separately because the quantity need not be equal in the two directions.\",\"properties\":{\"from_to\":{\"title\":\"FromTo\",\"type\":\"number\"},\"to_from\":{\"title\":\"ToFrom\",\"type\":\"number\"}},\"title\":\"FromTo_ToFrom\",\"type\":\"object\"},\"OperationalFlowLimit\":{\"description\":\"Operator-set flow limits on a directed branch: a minimum and a maximum flow in each direction, applied in addition to the branch's thermal rating.\",\"properties\":{\"from_to_min\":{\"title\":\"FromToMin\",\"type\":\"number\",\"minimum\":0},\"from_to_max\":{\"title\":\"FromToMax\",\"type\":\"number\",\"minimum\":0},\"to_from_min\":{\"title\":\"ToFromMin\",\"type\":\"number\",\"minimum\":0},\"to_from_max\":{\"title\":\"ToFromMax\",\"type\":\"number\",\"minimum\":0}},\"required\":[\"from_to_min\",\"from_to_max\",\"to_from_min\",\"to_from_max\"],\"title\":\"OperationalFlowLimit\",\"type\":\"object\"},\"FuelCurve\":{\"description\":\"Variable operation cost of a device expressed in fuel consumed, in the fuel quantity `fuel_units` names, together with the price that converts fuel to currency. Wraps a `ValueCurve` in input-output, incremental, or average-rate form, whose y axis is fuel per hour; exactly one of `fuel_cost` and `fuel_cost_time_series` supplies the price.\",\"properties\":{\"fuel_cost\":{\"type\":[\"number\",\"null\"],\"description\":\"Fixed fuel cost in USD per one `fuel_units` of fuel, or null when fuel_cost_time_series names a time-varying one. Exactly one of the two is set; producers and consumers enforce it.\"},\"fuel_cost_time_series\":{\"type\":[\"integer\",\"null\"],\"description\":\"Store-minted id of the fuel-cost time series association, or null when fuel_cost carries a fixed value. Exactly one of the two is set.\"},\"fuel_units\":{\"description\":\"The fuel quantity the curve's y axis counts (per hour) and `fuel_cost` is priced per. No default: an unstated fuel unit is ambiguous.\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/FuelUnit\"},\"power_units\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/UnitSystem\"},\"startup_fuel_offtake\":{\"description\":\"Fuel consumed during startup, as a curve in `fuel_units`.\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ValueCurve\"},\"variable_cost_type\":{\"const\":\"FUEL\",\"type\":\"string\",\"default\":\"FUEL\"},\"vom_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"}},\"required\":[\"value_curve\",\"power_units\",\"fuel_units\",\"vom_cost\",\"variable_cost_type\"],\"title\":\"FuelCurve\",\"type\":\"object\"},\"FuelUnit\":{\"description\":\"Fuel quantity a `FuelCurve` is expressed in: `MMBTU` (million British thermal units) or `GJ` (gigajoules) of heat content.\",\"enum\":[\"MMBTU\",\"GJ\"],\"title\":\"FuelUnit\",\"type\":\"string\"},\"FunctionData\":{\"description\":\"Raw mathematical data defining a function `f(x)` — coefficients or point tables with no units or interpretation attached. `function_type` selects the shape: linear, quadratic, piecewise linear through (x, y) points, or piecewise constant between x endpoints. What `x` and `y` stand for is supplied by whatever wraps this, and the `TIME_SERIES_*` variants hold a reference to a stored series in place of the numbers.\",\"discriminator\":{\"mapping\":{\"LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\",\"PIECEWISE_LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseLinearData\",\"PIECEWISE_STEP\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseStepData\",\"QUADRATIC\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/QuadraticFunctionData\",\"TIME_SERIES_LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesLinearFunctionData\",\"TIME_SERIES_QUADRATIC\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesQuadraticFunctionData\",\"TIME_SERIES_PIECEWISE_LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesPiecewiseLinearData\",\"TIME_SERIES_PIECEWISE_STEP\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesPiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/QuadraticFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseLinearData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseStepData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesLinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesQuadraticFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesPiecewiseLinearData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesPiecewiseStepData\"}],\"title\":\"FunctionData\",\"type\":\"object\"},\"GenericOperationCost\":{\"description\":\"Operating cost of a generation technology, selected by `cost_type` among the thermal (`THERMAL`), renewable (`RENEWABLE`), and hydro (`HYDRO_GEN`) generation cost representations.\",\"discriminator\":{\"mapping\":{\"RENEWABLE\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/RenewableGenerationCost\",\"THERMAL\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ThermalGenerationCost\",\"HYDRO_GEN\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/HydroGenerationCost\"},\"propertyName\":\"cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ThermalGenerationCost\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/RenewableGenerationCost\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/HydroGenerationCost\"}],\"title\":\"GenericOperationCost\",\"type\":\"object\"},\"HydroGenerationCost\":{\"description\":\"Cost representation for hydro gen units\",\"properties\":{\"cost_type\":{\"const\":\"HYDRO_GEN\",\"type\":\"string\",\"default\":\"HYDRO_GEN\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"HydroGenerationCost\",\"type\":\"object\"},\"HydroReservoirCost\":{\"description\":\"Cost representation for hydro reservoir\",\"properties\":{\"cost_type\":{\"const\":\"HYDRO_RES\",\"type\":\"string\",\"default\":\"HYDRO_RES\"},\"level_shortage_cost\":{\"default\":0.0,\"type\":\"number\"},\"level_surplus_cost\":{\"default\":0.0,\"type\":\"number\"},\"spillage_cost\":{\"default\":0.0,\"type\":\"number\"}},\"title\":\"HydroReservoirCost\",\"type\":\"object\"},\"HydroStorageGenerationCost\":{\"description\":\"Operating cost of hydro generation with storage, selected by `cost_type` between the hydro generation (`HYDRO_GEN`) and storage (`STORAGE`) cost representations.\",\"title\":\"HydroStorageGenerationCost\",\"type\":\"object\",\"discriminator\":{\"mapping\":{\"HYDRO_GEN\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/HydroGenerationCost\",\"STORAGE\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/StorageCost\"},\"propertyName\":\"cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/HydroGenerationCost\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/StorageCost\"}]},\"ImpedanceUnitBasis\":{\"description\":\"Unit basis a branch/injection impedance is stored in. NATURAL_UNITS: physical ohms (PSS/E RAW native for DC-line impedances). COMPONENT_BASE: per-unit on the component's own base (base_power MVA and voltage base); components whose per-unit data was historically on the system base record that system base in base_power, so there is no separate system-base option. PSS/E supplies device base for DC-line converters and CZ=2 transformer windings. A branch's shunt admittance halves (b, g) share the branch's one basis: NATURAL_UNITS stores them in siemens.\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_BASE\"],\"title\":\"ImpedanceUnitBasis\",\"type\":\"string\"},\"AdmittanceUnitBasis\":{\"description\":\"Unit basis a shunt admittance is stored in. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance). COMPONENT_BASE: per-unit on the component's own base (base_power MVA and voltage base) — a per-unit base, not a power at unity voltage, and not an alternative spelling of COMPONENT_MVAR; components whose per-unit data was historically on the system base record that system base in base_power. Fixed and switched shunts use ShuntAdmittanceUnitBasis instead, which omits COMPONENT_BASE because a shunt has no device MVA rating.\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_MVAR\",\"COMPONENT_BASE\"],\"title\":\"AdmittanceUnitBasis\",\"type\":\"string\"},\"ShuntAdmittanceUnitBasis\":{\"description\":\"Subset of AdmittanceUnitBasis for fixed and switched shunts: omits COMPONENT_BASE because a shunt has no device MVA rating to per-unitize against. NATURAL_UNITS: physical siemens. COMPONENT_MVAR: reactive power at unity voltage (Mvar for susceptance, MW for conductance) — PSS/E RAW native for shunts.\",\"enum\":[\"NATURAL_UNITS\",\"COMPONENT_MVAR\"],\"title\":\"ShuntAdmittanceUnitBasis\",\"type\":\"string\"},\"ImportExportCost\":{\"description\":\"Cost representation for static (non-time-varying) imports and exports with neighboring areas, together with the ancillary services offered alongside them. The offer curves are piecewise incremental cost curves with an implied zero cost at zero power, and a weekly energy limit bounds each direction. The time-varying counterpart is `ImportExportTimeSeriesCost`.\",\"properties\":{\"cost_type\":{\"const\":\"IMPORTEXPORT\",\"type\":\"string\",\"default\":\"IMPORTEXPORT\"},\"import_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"export_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"energy_import_weekly_limit\":{\"type\":\"number\",\"x-unit\":\"MWh\",\"description\":\"Weekly limit on imported energy, in MWh. MWh is the only representation: neither producers nor consumers rescale it by a system base. Units: MWh.\"},\"energy_export_weekly_limit\":{\"type\":\"number\",\"x-unit\":\"MWh\",\"description\":\"Weekly limit on exported energy, in MWh. MWh is the only representation: neither producers nor consumers rescale it by a system base. Units: MWh.\"}},\"required\":[\"energy_import_weekly_limit\",\"energy_export_weekly_limit\"],\"title\":\"ImportExportCost\",\"type\":\"object\"},\"ImportExportTimeSeriesCost\":{\"description\":\"Cost representation for time-varying imports and exports with neighboring areas. The static counterpart is ImportExportCost.\",\"properties\":{\"cost_type\":{\"const\":\"IMPORT_EXPORT_TIME_SERIES\",\"type\":\"string\",\"default\":\"IMPORT_EXPORT_TIME_SERIES\"},\"import_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\",\"description\":\"Import price curves whose value curve admits only the TIME_SERIES_INCREMENTAL variant; any other variant is rejected by the consuming constructor.\"},\"export_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\",\"description\":\"Export price curves whose value curve admits only the TIME_SERIES_INCREMENTAL variant; any other variant is rejected by the consuming constructor.\"},\"energy_import_weekly_limit\":{\"type\":\"number\",\"x-unit\":\"MWh\",\"description\":\"Weekly limit on imported energy, in MWh. MWh is the only representation: neither producers nor consumers rescale it by a system base. Units: MWh.\"},\"energy_export_weekly_limit\":{\"type\":\"number\",\"x-unit\":\"MWh\",\"description\":\"Weekly limit on exported energy, in MWh. MWh is the only representation: neither producers nor consumers rescale it by a system base. Units: MWh.\"},\"ancillary_service_offers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"}}},\"required\":[\"cost_type\",\"import_offer_curves\",\"export_offer_curves\",\"energy_import_weekly_limit\",\"energy_export_weekly_limit\",\"ancillary_service_offers\"],\"title\":\"ImportExportTimeSeriesCost\",\"type\":\"object\"},\"IncrementalCurve\":{\"description\":\"A curve whose y values are the marginal rate `f'(x)` at production level `x` — the native form for market bid stacks and incremental heat rate data. `initial_input` records the total input at the minimum production point, anchoring the absolute level and enabling conversion to an `InputOutputCurve`. Use `InputOutputCurve` when the data gives total cost at each output level.\",\"properties\":{\"curve_type\":{\"const\":\"INCREMENTAL\",\"type\":\"string\",\"default\":\"INCREMENTAL\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\",\"PIECEWISE_STEP\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseStepData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseStepData\"}]},\"initial_input\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the curve's y-axis unit.\"},\"input_at_zero\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the curve's y-axis unit.\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"IncrementalCurve\",\"type\":\"object\",\"x-curve-output\":-1},\"ChargeDischarge\":{\"description\":\"A pair of values, one for the charging (`charge`) and one for the discharging (`discharge`) direction of a quantity.\",\"properties\":{\"charge\":{\"type\":\"number\"},\"discharge\":{\"type\":\"number\"}},\"required\":[\"charge\",\"discharge\"],\"title\":\"ChargeDischarge\",\"type\":\"object\"},\"InOut\":{\"description\":\"A pair of values, one for the inbound (`in`) and one for the outbound (`out`) direction of a quantity.\",\"properties\":{\"in\":{\"type\":\"number\"},\"out\":{\"type\":\"number\"}},\"title\":\"InOut\",\"type\":\"object\"},\"InputOutputCurve\":{\"description\":\"A curve whose y values are the total input `f(x)` at production level `x` — currency per hour against MW in a cost curve, fuel per hour against MW in a fuel curve. The y axis is an absolute quantity, not a rate; use `IncrementalCurve` for marginal-rate data.\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"properties\":{\"curve_type\":{\"const\":\"INPUT_OUTPUT\",\"type\":\"string\",\"default\":\"INPUT_OUTPUT\"},\"function_data\":{\"discriminator\":{\"mapping\":{\"LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\",\"PIECEWISE_LINEAR\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseLinearData\",\"QUADRATIC\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/QuadraticFunctionData\"},\"propertyName\":\"function_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/QuadraticFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LinearFunctionData\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/PiecewiseLinearData\"}]},\"input_at_zero\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the curve's y-axis unit.\"}},\"required\":[\"function_data\",\"curve_type\"],\"title\":\"InputOutputCurve\",\"type\":\"object\",\"x-curve-output\":0},\"LinearFunctionData\":{\"description\":\"Data for a linear function `f(x) = proportional_term * x + constant_term`.\",\"properties\":{\"constant_term\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the wrapped function's output unit.\"},\"function_type\":{\"const\":\"LINEAR\",\"type\":\"string\",\"default\":\"LINEAR\"},\"proportional_term\":{\"type\":\"number\",\"x-curve-dimension\":[1,-1],\"description\":\"Units: the wrapped function's output unit per unit of its input.\"}},\"required\":[\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"LinearFunctionData\",\"type\":\"object\"},\"LoadCost\":{\"description\":\"Cost representation for controllable load units\",\"properties\":{\"cost_type\":{\"const\":\"LOAD\",\"type\":\"string\",\"default\":\"LOAD\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"}},\"required\":[\"variable_operation_cost\"],\"title\":\"LoadCost\",\"type\":\"object\"},\"LossCurve\":{\"description\":\"Losses of a device as a function of the power flow through it, together with the power basis the curve is expressed in. A loss driven by current instead is a `CurrentLossCurve`. `power_units` governs BOTH axes: a loss curve's y values are power in the same base as its x values, so a change of base rescales both. This is what separates it from a cost curve, whose y axis is currency and so rides through a change of base untouched. Units: both axes per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"properties\":{\"power_units\":{\"default\":\"NATURAL_UNITS\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/UnitSystem\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LossValueCurve\"}},\"required\":[\"value_curve\",\"power_units\"],\"title\":\"LossCurve\",\"type\":\"object\",\"x-curve-axes\":{\"x\":\"ActivePower\",\"y\":\"ActivePower\"}},\"CurrentLossCurve\":{\"description\":\"Losses of a device as a function of the current through it (a converter's DC current), together with the basis the curve is expressed in. `power_units` governs both axes: the y values are power and the x values current, each per-unit on the component's base (current's base being base power over base voltage) or natural. Units: x-axis per power_units — NATURAL_UNITS: kA, COMPONENT_BASE: pu ; y-axis per power_units — NATURAL_UNITS: MW, COMPONENT_BASE: pu .\",\"properties\":{\"power_units\":{\"default\":\"NATURAL_UNITS\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/UnitSystem\"},\"value_curve\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/LossValueCurve\"}},\"required\":[\"value_curve\",\"power_units\"],\"title\":\"CurrentLossCurve\",\"type\":\"object\",\"x-curve-axes\":{\"x\":\"CurrentFlow\",\"y\":\"ActivePower\"}},\"LossValueCurve\":{\"description\":\"The shape of a loss curve, selected by `curve_type`. `INPUT_OUTPUT` gives the total loss at each flow level -- a constant loss plus a proportional loss rate, in MW of loss per MW of flow. `INCREMENTAL` gives the marginal loss rate instead, the form a piecewise model uses to give different proportional losses on different flow segments. Individual loss fields accept narrower sets of shapes than this union admits; the consuming data layer enforces that, not this schema.\",\"title\":\"LossValueCurve\",\"discriminator\":{\"mapping\":{\"INCREMENTAL\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/IncrementalCurve\",\"INPUT_OUTPUT\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"},\"propertyName\":\"curve_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/IncrementalCurve\"}],\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"type\":\"object\"},\"MassUnit\":{\"description\":\"Mass unit an emission quantity is reported in: kilograms, pounds, short tons (2000 lb), or metric tons (1000 kg).\",\"enum\":[\"KG\",\"LB\",\"SHORT_TON\",\"METRIC_TON\"],\"title\":\"MassUnit\",\"type\":\"string\"},\"CurveStyles\":{\"description\":\"Curve-clearing style for a bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.\",\"type\":\"integer\",\"enum\":[0,1],\"default\":0,\"title\":\"CurveStyles\"},\"CurveMultiStep\":{\"description\":\"Multi-step block indicator for a bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve style: curve style is the quantity structure, this is the time structure, and they compose.\",\"type\":\"integer\",\"enum\":[0,1],\"default\":0,\"title\":\"CurveMultiStep\"},\"MarketBidCost\":{\"description\":\"Cost representation for static (non-time-varying) market bids of energy and ancillary services.\",\"properties\":{\"cost_type\":{\"const\":\"MARKET_BID\",\"type\":\"string\",\"default\":\"MARKET_BID\"},\"minimum_energy_offer\":{\"description\":\"Minimum-energy offer: cost to operate at minimum stable level, in \$/MWh at the curve's minimum power, stored as submitted. \$/h sources convert at parse (MEO = no-load cost / P_min). Legacy scalar promotion: a bare scalar value `s` from a legacy source converts to an `InputOutputCurve` of `LinearFunctionData` with `constant_term = s` and `proportional_term = 0`.\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"},\"start_up\":{\"description\":\"Start-up cost at different stages of the thermal cycle (hot, warm, cold).\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/StartUpStages\"},\"shut_down\":{\"description\":\"Shut-down cost. Legacy scalar promotion: a bare scalar value `s` from a legacy source converts to an `InputOutputCurve` of `LinearFunctionData` with `constant_term = s` and `proportional_term = 0`.\",\"default\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/InputOutputCurve\"},\"incremental_offer_curves\":{\"description\":\"Sell offer curves data as a `CostCurve` of `PiecewiseIncrementalCurve`.\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"decremental_offer_curves\":{\"description\":\"Buy offer curves data as a `CostCurve` of `PiecewiseIncrementalCurve`.\",\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"ancillary_service_offers\":{\"description\":\"IDs of the ancillary service components that this market bid offers into.\",\"type\":\"array\",\"items\":{\"type\":\"integer\"}},\"incremental_slope\":{\"description\":\"Linear-interpolation flag for the incremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"decremental_slope\":{\"description\":\"Linear-interpolation flag for the decremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"curve_style\":{\"description\":\"Curve-clearing style for the bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CurveStyles\"},\"curve_multistep\":{\"description\":\"Multi-step block indicator for the bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve_style: curve_style is the quantity structure, curve_multistep is the time structure, and they compose.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CurveMultiStep\"}},\"required\":[\"minimum_energy_offer\",\"start_up\",\"shut_down\",\"incremental_offer_curves\",\"decremental_offer_curves\",\"ancillary_service_offers\"],\"title\":\"MarketBidCost\",\"type\":\"object\"},\"MarketBidTimeSeriesCost\":{\"description\":\"Cost representation for time-varying market bids of energy and ancillary services. The static counterpart is MarketBidCost.\",\"properties\":{\"cost_type\":{\"const\":\"MARKET_BID_TIME_SERIES\",\"type\":\"string\",\"default\":\"MARKET_BID_TIME_SERIES\"},\"minimum_energy_offer\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesInputOutputCurve\",\"description\":\"Minimum-energy offer: cost to operate at minimum stable level, in \$/MWh at the curve's minimum power, stored as submitted. \$/h sources convert at parse (MEO = no-load cost / P_min). Time-series-backed linear curve; only the TIME_SERIES_LINEAR function-data variant is admissible here — the consuming constructor rejects any other.\"},\"start_up_association_id\":{\"type\":\"integer\",\"description\":\"Store-minted id of a time series of three-stage (hot, warm, cold) start-up costs.\"},\"shut_down\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TimeSeriesInputOutputCurve\",\"description\":\"Shut-down cost as a time-series-backed linear curve. Only the TIME_SERIES_LINEAR function-data variant is admissible here; the consuming constructor rejects any other.\"},\"incremental_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\",\"description\":\"Sell offer curves whose value curve is a time-series-backed piecewise incremental curve. Only the TIME_SERIES_INCREMENTAL variant is admissible here; any other variant is rejected by the consuming constructor.\"},\"decremental_offer_curves\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\",\"description\":\"Buy offer curves whose value curve is a time-series-backed piecewise incremental curve. Only the TIME_SERIES_INCREMENTAL variant is admissible here; any other variant is rejected by the consuming constructor.\"},\"ancillary_service_offers\":{\"type\":\"array\",\"items\":{\"type\":\"integer\"},\"description\":\"IDs of the ancillary service components that this bid offers into.\"},\"incremental_slope\":{\"description\":\"Linear-interpolation flag for the incremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"decremental_slope\":{\"description\":\"Linear-interpolation flag for the decremental offer curves; false (default) is the step interpretation. Mutually exclusive with block groups on the same curve.\",\"type\":\"boolean\",\"default\":false},\"curve_style\":{\"description\":\"Curve-clearing style for the bid: 0 = VARIABLE (default; continuous quantity with one or more segments); 1 = FIXED (all-or-nothing block with a single segment). FIXED is mutually exclusive with incremental_slope/decremental_slope and requires a single-segment offer curve.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CurveStyles\"},\"curve_multistep\":{\"description\":\"Multi-step block indicator for the bid: 0 = SINGLE_STEP (default; each step of the bid clears independently); 1 = MULTI_STEP (the bid must be awarded as one block across every step it covers). Counted in model steps so it applies at any resolution. Independent of curve_style: curve_style is the quantity structure, curve_multistep is the time structure, and they compose.\",\"default\":0,\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CurveMultiStep\"}},\"required\":[\"cost_type\",\"minimum_energy_offer\",\"start_up_association_id\",\"shut_down\",\"incremental_offer_curves\",\"decremental_offer_curves\",\"ancillary_service_offers\"],\"title\":\"MarketBidTimeSeriesCost\",\"type\":\"object\"},\"MinMax\":{\"description\":\"A pair of values bounding a quantity from below (`min`) and from above (`max`).\",\"properties\":{\"max\":{\"title\":\"Max\",\"type\":\"number\"},\"min\":{\"title\":\"Min\",\"type\":\"number\"}},\"title\":\"MinMax\",\"type\":\"object\"},\"MinMaxByKey\":{\"description\":\"A mapping from a stringified float key to the `MinMax` bound that applies at that key.\",\"additionalProperties\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/MinMax\"},\"title\":\"MinMaxByKey\",\"type\":\"object\"},\"OutageFactors\":{\"description\":\"A pair of values representing planned and forced outage factors as fractions of total availability.\",\"properties\":{\"planned\":{\"title\":\"Planned\",\"type\":\"number\"},\"forced\":{\"title\":\"Forced\",\"type\":\"number\"}},\"title\":\"OutageFactors\",\"type\":\"object\"},\"PiecewiseLinearData\":{\"description\":\"Data for a piecewise linear function defined by (x, y) points and interpolated linearly between consecutive ones. The y values are absolute values at each x, not per-segment slopes; use `PiecewiseStepData` when the data gives per-segment rates. Points run in ascending x order, and two of them define one segment.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_LINEAR\",\"type\":\"string\",\"default\":\"PIECEWISE_LINEAR\"},\"points\":{\"items\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/TwoDimensionalFunctionPoint\"},\"type\":\"array\"}},\"required\":[\"points\",\"function_type\"],\"title\":\"PiecewiseLinearData\",\"type\":\"object\"},\"PiecewiseStepData\":{\"description\":\"Data for a step function, constant on each segment, defined by the x coordinates of the segment endpoints and one y value per segment. The y values are per-segment rates, not absolute values; use `PiecewiseLinearData` when the data gives a value at each point. `x_coords` ascends and holds at least two entries, and `y_coords` holds exactly one fewer.\",\"properties\":{\"function_type\":{\"const\":\"PIECEWISE_STEP\",\"type\":\"string\",\"default\":\"PIECEWISE_STEP\"},\"x_coords\":{\"items\":{\"type\":\"number\",\"x-curve-dimension\":[0,1],\"description\":\"Units: the wrapped function's input unit.\"},\"type\":\"array\"},\"y_coords\":{\"items\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the wrapped function's output unit.\"},\"type\":\"array\"}},\"required\":[\"x_coords\",\"y_coords\",\"function_type\"],\"title\":\"PiecewiseStepData\",\"type\":\"object\"},\"PollutantType\":{\"description\":\"Pollutant an emission rate is reported for, spanning greenhouse gases (`CO2`, `CO2E`, `CH4`, `N2O`), criteria pollutants (`NOX`, `SO2`, `CO`, `VOC`, `PM25`, `PM10`), and toxics (`HG`, `HAP`), with `CUSTOM` for a user-defined pollutant.\",\"enum\":[\"CO2\",\"CO2E\",\"CH4\",\"N2O\",\"NOX\",\"SO2\",\"CO\",\"VOC\",\"PM25\",\"PM10\",\"HG\",\"HAP\",\"CUSTOM\"],\"title\":\"PollutantType\",\"type\":\"string\"},\"PrimeMovers\":{\"description\":\"Prime mover of a generating unit — the engine, turbine, water wheel, or similar machine that drives the generator — using the code set from the EIA Form 923 instructions. `PVe` is photovoltaic, spelled that way so it does not collide with the `PV` bus type.\",\"enum\":[\"BA\",\"BT\",\"CA\",\"CC\",\"CE\",\"CP\",\"CS\",\"CT\",\"ES\",\"FC\",\"FW\",\"GT\",\"HA\",\"HB\",\"HK\",\"HY\",\"IC\",\"PS\",\"OT\",\"ST\",\"PVe\",\"WT\",\"WS\"],\"title\":\"PrimeMovers\",\"type\":\"string\"},\"ProductionVariableCostCurve\":{\"description\":\"Variable production cost of a device, selected by `variable_cost_type` between a curve denominated directly in currency (`COST`) and one denominated in fuel with a separate fuel price (`FUEL`).\",\"title\":\"ProductionVariableCostCurve\",\"discriminator\":{\"mapping\":{\"COST\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\",\"FUEL\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/FuelCurve\"},\"propertyName\":\"variable_cost_type\"},\"oneOf\":[{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/FuelCurve\"}],\"type\":\"object\"},\"QuadraticFunctionData\":{\"description\":\"Data for a quadratic function `f(x) = quadratic_term * x^2 + proportional_term * x + constant_term`. A non-negative `quadratic_term` makes the function convex.\",\"properties\":{\"constant_term\":{\"type\":\"number\",\"x-curve-dimension\":[1,0],\"description\":\"Units: the wrapped function's output unit.\"},\"function_type\":{\"const\":\"QUADRATIC\",\"type\":\"string\",\"default\":\"QUADRATIC\"},\"proportional_term\":{\"type\":\"number\",\"x-curve-dimension\":[1,-1],\"description\":\"Units: the wrapped function's output unit per unit of its input.\"},\"quadratic_term\":{\"type\":\"number\",\"x-curve-dimension\":[1,-2],\"description\":\"Units: the wrapped function's output unit per unit of its input squared.\"}},\"required\":[\"quadratic_term\",\"proportional_term\",\"constant_term\",\"function_type\"],\"title\":\"QuadraticFunctionData\",\"type\":\"object\"},\"RenewableGenerationCost\":{\"description\":\"Cost representation for renewable generation units\",\"properties\":{\"cost_type\":{\"const\":\"RENEWABLE\",\"type\":\"string\",\"default\":\"RENEWABLE\"},\"curtailment_cost\":{\"default\":{\"variable_cost_type\":\"COST\",\"value_curve\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}},\"vom_cost\":{\"curve_type\":\"INPUT_OUTPUT\",\"function_data\":{\"function_type\":\"LINEAR\",\"constant_term\":0,\"proportional_term\":0}}},\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"fixed\":{\"type\":\"number\",\"default\":0.0}},\"required\":[\"variable_operation_cost\"],\"title\":\"RenewableGenerationCost\",\"type\":\"object\"},\"ReservoirLocation\":{\"description\":\"Position of a hydro reservoir relative to its turbine: `HEAD` upstream of the turbine, typically at higher elevation; `TAIL` downstream, at lower or equal elevation.\",\"enum\":[\"HEAD\",\"TAIL\"],\"title\":\"ReservoirLocation\",\"type\":\"string\"},\"StartUpShutDown\":{\"description\":\"A pair of values, one for the start-up phase and one for the shut-down phase of a unit's cycle.\",\"properties\":{\"startup\":{\"title\":\"StartUp\",\"type\":\"number\"},\"shutdown\":{\"title\":\"ShutDown\",\"type\":\"number\"}},\"title\":\"StartUpShutDown\",\"type\":\"object\"},\"StartUpStages\":{\"description\":\"A triple of values, one for each stage of a thermal unit's start-up: `hot`, `warm`, and `cold`.\",\"properties\":{\"startup_stages_type\":{\"const\":\"STAGES\",\"type\":\"string\",\"default\":\"STAGES\"},\"cold\":{\"type\":\"number\"},\"hot\":{\"type\":\"number\"},\"warm\":{\"type\":\"number\"}},\"required\":[\"hot\",\"warm\",\"cold\"],\"title\":\"StartUpStages\",\"type\":\"object\"},\"StorageCost\":{\"description\":\"Cost representation for storage units\",\"properties\":{\"cost_type\":{\"const\":\"STORAGE\",\"type\":\"string\",\"default\":\"STORAGE\"},\"charge_variable_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"discharge_variable_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/CostCurve\"},\"fixed\":{\"default\":0.0,\"type\":\"number\"},\"shut_down\":{\"default\":0.0,\"type\":\"number\"},\"start_up\":{\"default\":0.0,\"oneOf\":[{\"type\":\"number\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ChargeDischarge\"}]},\"energy_shortage_cost\":{\"default\":0.0,\"type\":\"number\"},\"energy_surplus_cost\":{\"default\":0.0,\"type\":\"number\"}},\"required\":[\"fixed\",\"start_up\",\"shut_down\"],\"title\":\"StorageCost\",\"type\":\"object\"},\"StorageTech\":{\"description\":\"defines the storage technology used in an energy Storage system, based on the options in EIA form 923.\",\"enum\":[\"PTES\",\"LIB\",\"LAB\",\"FLWB\",\"SIB\",\"ZIB\",\"HGS\",\"LAES\",\"OTHER_CHEM\",\"OTHER_MECH\",\"OTHER_THERM\"],\"title\":\"StorageTech\",\"type\":\"string\"},\"CapitalCost\":{\"description\":\"Investment cost for candidate generation and transmission technologies which includes overnight capital costs and last-mile interconnection costs.\",\"properties\":{\"capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ValueCurve\"},\"interconnection_cost\":{\"type\":\"number\",\"default\":0.0}},\"required\":[\"capital_cost\"],\"title\":\"CapitalCost\",\"type\":\"object\"},\"StorageCapitalCost\":{\"description\":\"Investment cost for candidate generation and transmission technologies which includes overnight capital costs and last-mile interconnection costs.\",\"properties\":{\"charge_capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ValueCurve\"},\"discharge_capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ValueCurve\"},\"energy_capital_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ValueCurve\"},\"interconnection_cost\":{\"type\":\"number\",\"default\":0.0}},\"required\":[\"charge_capital_cost\",\"discharge_capital_cost\",\"energy_capital_cost\",\"interconnection_cost\"],\"title\":\"StorageCapitalCost\",\"type\":\"object\"},\"ThermalFuels\":{\"description\":\"Thermal fuels that reflect options in the EIA annual energy review.\",\"enum\":[\"ANTHRACITE_COAL\",\"BITUMINOUS_COAL\",\"LIGNITE_COAL\",\"SUBBITUMINOUS_COAL\",\"WASTE_COAL\",\"REFINED_COAL\",\"SYNTHESIS_GAS_COAL\",\"DISTILLATE_FUEL_OIL\",\"JET_FUEL\",\"KEROSENE\",\"PETROLEUM_COKE\",\"RESIDUAL_FUEL_OIL\",\"PROPANE\",\"SYNTHESIS_GAS_PETROLEUM_COKE\",\"WASTE_OIL\",\"BLAST_FURNACE_GAS\",\"NATURAL_GAS\",\"OTHER_GAS\",\"AG_BYPRODUCT\",\"MUNICIPAL_WASTE\",\"OTHER_BIOMASS_SOLIDS\",\"WOOD_WASTE_SOLIDS\",\"OTHER_BIOMASS_LIQUIDS\",\"SLUDGE_WASTE\",\"BLACK_LIQUOR\",\"WOOD_WASTE_LIQUIDS\",\"LANDFILL_GAS\",\"OTHER_BIOMASS_GAS\",\"NUCLEAR\",\"WASTE_HEAT\",\"TIRE_DERIVED_FUEL\",\"COAL\",\"GEOTHERMAL\",\"OTHER\"],\"title\":\"ThermalFuels\",\"type\":\"string\"},\"ThermalGenerationCost\":{\"title\":\"ThermalGenerationCost\",\"description\":\"Cost representation for thermal generation units\",\"properties\":{\"cost_type\":{\"const\":\"THERMAL\",\"type\":\"string\",\"default\":\"THERMAL\"},\"fixed\":{\"description\":\"Fixed cost of keeping the unit online. For some cost represenations this field can be duplicative\",\"type\":\"number\"},\"shut_down\":{\"description\":\"Cost to turn the unit off\",\"type\":\"number\"},\"start_up\":{\"discriminator\":{\"mapping\":{\"STAGES\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/StartUpStages\"},\"propertyName\":\"startup_stages_type\"},\"description\":\"Start-up cost can take linear or multi-stage cost\",\"oneOf\":[{\"type\":\"number\"},{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/StartUpStages\"}]},\"variable_operation_cost\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/ProductionVariableCostCurve\"}},\"required\":[\"variable_operation_cost\",\"fixed\",\"start_up\",\"shut_down\"],\"type\":\"object\"},\"TimeSeriesAverageRateCurve\":{\"properties\":{\"curve_type\":{\"const\":\"TIME_SERIES_AVERAGE_RATE\",\"type\":\"string\",\"default\":\"TIME_SERIES_AVERAGE_RATE\"},\"function_data\":{\"\$ref\":\"https://openapi.invalid/schema/external-30ade9e32c244c2702f7.json#/\$defs/FunctionData\",\"description\":\"Only TIME_SERIES_LINEAR or TIME_SERIES_PIECEWISE_STEP is admissible here; all other FunctionData variants, static or time-series-backed, are rejected by the consuming constructor.\"},\"initial_input_association_id\":{\"type\":[\"integer\",\"null\"],\"description\":\"Store-minted id 