        retrieval="https://openapi.invalid/schema/external-3f22d0da59fc563e08e7.json",
        media_type="application/schema+json",
        json="{\"\$schema\":\"https://json-schema.org/draft/2020-12/schema\",\"description\":\"Parameter of a full order flux stator-rotor model without zero sequence flux in the stator. The derivative of stator fluxes (ψd and ψq) is NOT neglected. Only one q-axis damping circuit is considered. All parameters are in machine per unit. Refer to Chapter 3 of Power System Stability and Control by P. Kundur or Chapter 11 of Power System Dynamics: Stability and Control, by J. Machowski, J. Bialek and J. Bumby, for more details. Note that the models are somewhat different (but equivalent) due to the different Park Transformation used in both books\",\"properties\":{\"id\":{\"description\":\"Unique integer identifier for this component\",\"type\":\"integer\"},\"R\":{\"description\":\"Resistance after EMF. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Resistance\"},\"R_f\":{\"description\":\"Field rotor winding resistance. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Resistance\"},\"R_1d\":{\"description\":\"Damping rotor winding resistance on d-axis in per unit. This value is denoted as RD in Machowski. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Resistance\"},\"R_1q\":{\"description\":\"Damping rotor winding resistance on q-axis in per unit. This value is denoted as RQ in Machowski. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Resistance\"},\"L_d\":{\"description\":\"Inductance of fictitious damping that represent the effect of the three-phase stator winding in the d-axis of the rotor, in per unit. This value is denoted as Lad + Ll in Kundur (and Ld in Machowski). Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_q\":{\"description\":\"Inductance of fictitious damping that represent the effect of the three-phase stator winding in the q-axis of the rotor, in per unit. This value is denoted as Laq + Ll in Kundur (and Ld in Machowski). Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_ad\":{\"description\":\"Mutual inductance between stator winding and rotor field (and damping) winding inductance on d-axis, in per unit. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_aq\":{\"description\":\"Mutual inductance between stator winding and rotor damping winding inductance on q-axis, in per unit. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_f1d\":{\"description\":\"Mutual inductance between rotor field winding and rotor damping winding inductance on d-axis, in per unit. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_ff\":{\"description\":\"Field rotor winding inductance, in per unit. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_1d\":{\"description\":\"Inductance of the d-axis rotor damping circuit, in per unit. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"},\"L_1q\":{\"description\":\"Inductance of the q-axis rotor damping circuit, in per unit. Units: pu.\",\"type\":\"number\",\"x-unit\":\"pu\",\"x-quantity\":\"Reactance\"}},\"required\":[\"id\",\"R\",\"R_f\",\"R_1d\",\"R_1q\",\"L_d\",\"L_q\",\"L_ad\",\"L_aq\",\"L_f1d\",\"L_ff\",\"L_1d\",\"L_1q\"],\"title\":\"FullMachine\",\"type\":\"object\"}",
